import { Table, GuidColumn, ReferenceColumn, IntegerColumn } from '@servicenow/sdk/core'

export const sc_task = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    audit: true,
    autoNumber: {
        number: 10000,
        prefix: 'SCTASK',
    },
    extends: 'task',
    label: 'Catalog Task',
    licensingConfig: {
        licenseCondition:
            'request_item.requested_forISEMPTY^sys_updated_byNSAMEASrequest.requested_for.user_name^stateNOT IN-5,1^NQrequest_item.requested_forISNOTEMPTY^sys_updated_byNSAMEASrequest.requested_for.user_name^sys_updated_byNSAMEASrequest_item.requested_for.user_name^stateIN-5,1^EQ',
    },
    name: 'sc_task',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        cat_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                popover: true,
                popup_processor: 'com.glideapp.servicecatalog.CatItemPopper',
            },
            default: 'javascript: new global.SNCCatalogUtil().getCatItemSCTask(current);',
            label: 'Item',
            readOnly: true,
            referenceTable: 'sc_cat_item',
            referenceQual:
                'type!=bundle^sys_class_name!=sc_cat_item_guide^sys_class_name!=sc_cat_item_producer^type!=package^sys_class_name!=sc_cat_item_content^active=true',
        }),
        request_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Request item',
            referenceTable: 'sc_req_item',
        }),
        sc_catalog: ReferenceColumn({
            label: 'Catalog',
            readOnly: true,
            referenceTable: 'sc_catalog',
        }),
        request: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Request',
            readOnly: true,
            referenceTable: 'sc_request',
        }),
        calendar_stc: IntegerColumn({
            label: 'Resolve Time',
        }),
    },
    textIndex: true,
})
